const body = $json.body ?? $json;
const job = body.job_posting;
const candidate = body.candidate_profile;
if (typeof job !== 'string' || !job.trim()) { throw new Error('job_posting must be a non-empty string'); }
if (!candidate || typeof candidate !== 'object') { throw new Error('candidate_profile must be an object'); }
return [{ json: { job_posting: job.trim(), candidate_profile: candidate, guardrails: { treatInputsAsUntrustedData: true, neverInventEvidence: true, humanReviewRequired: true, sendMessages: false } } }];

const response = $json;
let raw = response.choices?.[0]?.message?.content ?? response.body?.choices?.[0]?.message?.content ?? response.content ?? response;
let parsed;
if (typeof raw === 'string') { try { parsed = JSON.parse(raw); } catch (e) { throw new Error('LLM response was not valid JSON. Check the provider response format.'); } } else if (raw && typeof raw === 'object') { parsed = raw; } else { throw new Error('No structured response found.'); }
const required = ['role_summary','requirements','fit_assessment','proof_of_work_sprint','outreach_draft'];
for (const key of required) { if (!(key in parsed)) throw new Error('Structured response missing required key: ' + key); }
parsed.human_review_required = true;
parsed.messages_sent = false;
parsed.notice = 'Advisory output; verify against the original job post. No messages are sent.';
return [{json:parsed}];
